/* R-381 interaction study. All mutations stay in this page's memory. */
const projects = [
  { id:'reader', name:'Markdown 阅读器', description:'随时阅读，持续积累', active:true, subagents:false, work:{ id:'R-001', title:'移动端 Markdown 上下文库与 API Agent', status:'开发中', priority:'P1', done:2, total:5 }, next:'接通附件保存与全文检索', updated:'3 分钟前', goal:'在手机上阅读、检索和整理自己的 Markdown 与附件。', note:'真机 OCR 等待设备；附件检索继续推进。', conversations:[{id:'main',title:'阅读器持续开发'},{id:'search',title:'附件检索体验'}], goals:[] },
  { id:'kanzei', name:'kanzei code', description:'多项目长期开发工作台', active:true, subagents:true, work:{ id:'R-365', title:'网页搜索与抓取升级', status:'开发中', priority:'P1', done:1, total:3 }, next:'验证搜索结果与引用回传', updated:'8 分钟前', goal:'让多个项目自主推进，集中查看成果与纠正决定。', note:'当前搜索链路验证中；工作台导航改造已登记。', conversations:[{id:'main',title:'搜索链路开发'},{id:'design',title:'工作台产品设计'}], goals:[] },
  { id:'agentos', name:'Akashic-AgentOS', description:'可信工作流与成果', active:false, subagents:false, work:{ id:'R-001', title:'工作流结果的来源与导出', status:'待推进', priority:'P2', done:0, total:2 }, next:'等待安排下一项工作', updated:'昨天', goal:'让工作流结果可追溯、可解释并便于交付。', note:'项目空闲。查看进度不会自动启动执行。', conversations:[{id:'main',title:'工作流结果讨论'}], goals:[] },
];
const reviews = [
  {id:'decision-reader',project:'reader',kind:'decision',label:'决策复核',title:'PDF 先用本地提取，OCR 按需补充',body:'先把阅读与检索闭环交付；扫描文档保留原文件和识别状态，待真机验证后接通 OCR。',reason:'本地提取可先形成可用成果，设备缺口只影响 OCR。',done:false},
  {id:'delivery-reader',project:'reader',kind:'delivery',label:'待你试用',title:'附件保存与重新打开',body:'可以附加文件，重新打开后继续查看。机器验证已通过；等待一次实际试用。',reason:'示例交付 · B2 · 验证绑定当前示例版本',done:false},
  {id:'decision-kanzei',project:'kanzei',kind:'decision',label:'决策复核',title:'低频搜索工具按需加载',body:'保留常用工具，其余经目录发现后加载，减少每步常驻上下文。',reason:'搜索能力仍可发现，避免无关工具长期占用当前工作上下文。',done:false},
];
const preferences = [
  {scope:'所有项目',text:'普通实现选择先决定并留档，集中交付时复核。',source:'已确认偏好 · 示例'},
  {scope:'Markdown 阅读器',text:'优先完成本地阅读与检索，再扩展网络能力。',source:'项目偏好 · 示例'},
];
const drafts = new Map();
const messages = new Map();
const scrolls = new Map();
let previousRoute = '';
let updateCount = 0;
let toastTimer;
const $ = (selector) => document.querySelector(selector);
const escape = (value) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const project = id => projects.find(p => p.id === id);
const pending = () => reviews.filter(r => !r.done).length;
const pRoute = (p, tab='overview', conversation='') => `#project/${p.id}/${tab}${conversation ? '/'+conversation : ''}`;
function toast(text){ const el=$('#toast'); el.textContent=text; el.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>{el.hidden=true;},3500); }
function counts(){ document.querySelectorAll('[data-inbox-count]').forEach(el=>{el.textContent=pending();}); }
function meter(p){return `<span class="meter" data-meter="${p.id}">${Array.from({length:p.work.total},(_,i)=>`<i class="segment ${i<p.work.done?'done':i===p.work.done?'next':''}" aria-hidden="true"></i>`).join('')}<span class="meter-label">批次 ${p.work.done}/${p.work.total}</span></span>`;}
function requirement(p){return `<button class="requirement" data-detail="${p.id}" aria-label="查看 ${p.name} 的 ${p.work.id} 进度"><span class="req-meta"><span class="req-id">${p.work.id}</span><span class="phase">${p.work.status}</span><span class="priority">${p.work.priority}</span></span><span class="req-title">${p.work.title}</span>${meter(p)}</button>`;}
function projectRow(p){return `<article class="project-row filter-match" data-project="${p.id}" data-active="${p.active}"><div class="project-identity"><a href="${pRoute(p)}">${p.name}</a><p>${p.description}</p><span class="state ${p.active?'':'idle'}">${p.active?'正在推进 · 1 条主线':'空闲'}</span></div><div>${requirement(p)}</div><div class="next-step"><span data-next="${p.id}">${p.next}</span><span class="updated" data-updated="${p.id}">${p.updated}</span></div><a class="project-enter" href="${pRoute(p)}">进入项目 ↗</a></article>`;}
function home(){return `<div class="page-head"><div><div class="eyebrow">WORKBENCH</div><h1>工作台</h1><p>看看项目推进到哪里，以及哪些事需要你。</p></div><button class="primary" data-new-goal>＋ 新目标</button></div><div class="overview-counts"><div><strong>2</strong>项目正在推进</div><div><strong data-inbox-count>${pending()}</strong>项待你处理</div></div><div class="attention-strip"><span>阅读器 · 真机 OCR 待补设备</span><span class="muted">附件检索继续推进</span><a href="${pRoute(project('reader'))}">查看详情 →</a></div><div class="section-head"><h2>项目进展</h2><select id="project-filter" class="filter" aria-label="筛选项目状态"><option value="all">全部项目 · 3</option><option value="active">正在推进 · 2</option><option value="idle">空闲 · 1</option></select></div><div class="table-head"><span>项目</span><span>当前工作</span><span>最近进展</span><span></span></div>${projects.map(projectRow).join('')}<div class="lower-note"><span>批次进度、机器验证和用户试用分别记录。</span><a href="#inbox">查看交付与决策 →</a></div>`;}
function projectPage(p,tab,conversation){return `<div class="page-head"><div><div class="eyebrow">PROJECT / ${p.id.toUpperCase()}</div><h1>${p.name}</h1><p>${p.description}</p></div><div class="project-controls"><span class="state ${p.active?'':'idle'}">${p.active?'自主推进中':'空闲'}</span><button class="quiet" data-capabilities="${p.id}">项目能力 ↗</button></div></div><nav class="project-tabs" aria-label="项目页面">${[['overview','概览'],['work','工作'],['conversations','对话']].map(([key,label])=>`<a href="${pRoute(p,key)}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${tab==='conversations'?chat(p,conversation):tab==='work'?work(p):overview(p)}`;}
function overview(p){return `<div class="project-layout"><div><section class="section-block"><h3>项目目标</h3><p class="goal-description">${p.goal}</p><p class="muted">${p.note}</p></section><section class="section-block"><div class="section-head"><h2>当前工作</h2><a class="muted" href="${pRoute(p,'work')}">全部工作 →</a></div><div class="work-detail">${requirement(p)}<p class="task-foot">当前阶段：<span data-next="${p.id}">${p.next}</span></p></div></section><a class="link-button" href="${pRoute(p,'conversations')}">进入项目对话 →</a></div><div><section class="section-block"><h3>执行状态</h3><div class="simple-line">主线<span>${p.active?'运行中':'未运行'}</span></div><div class="simple-line">子代理<span data-agent-label="${p.id}">${p.subagents?'可用 · 当前 0 个':'关闭'}</span></div><div class="simple-line">后台验证<span>${p.id==='kanzei'?'1 项进行中':'无在途验证'}</span></div><p class="inline-note">${p.active?'离开本页后，项目继续推进。':'空闲项目只保留状态摘要。'}</p><button class="quiet" data-capabilities="${p.id}">管理项目能力 ↗</button></section><section class="section-block"><h3>待处理</h3><div class="simple-line">交付与决策<span>${reviews.filter(r=>r.project===p.id&&!r.done).length} 项</span></div><a class="link-button" href="#inbox/${p.id}">查看本项目待处理 →</a></section></div></div>`;}
function work(p){return `<div class="section-head"><h2>在途与待办</h2><button class="quiet" data-new-goal="${p.id}">＋ 新目标</button></div><div class="work-detail">${requirement(p)}<p class="task-foot">${p.active?'负责线路：主线 · 运行中':'尚未领取'} · 实现、验证、试用分开查看</p></div>${p.goals.map(g=>`<div class="work-detail"><div class="req-meta">新目标 <span class="phase">待安排</span></div><h3>${escape(g)}</h3></div>`).join('')}<p class="inline-note">工作持续保留；结束一次对话不会结束整个项目。</p>`;}
function chat(p,requested){const c=p.conversations.find(c=>c.id===requested)||p.conversations[0];const key=`${p.id}/${c.id}`;return `<div class="chat-layout"><nav class="chat-nav" aria-label="${p.name}的对话">${p.conversations.map(item=>`<button class="${item.id===c.id?'active':''}" data-chat="${p.id}/${item.id}">${escape(item.title)}</button>`).join('')}<button class="new-chat" data-new-chat="${p.id}">＋ 新对话</button></nav><div class="chat-main"><div class="chat-head"><strong>${escape(c.title)}</strong><button class="link-button" data-detail="${p.id}">${p.work.id} ↗</button></div><div class="chat-log" aria-label="对话内容"><div class="message"><small>你</small><p>继续当前工作，记录决策，完成一批后交给我试用。</p></div><div class="message"><small>Kanzei · 示例回复</small><p>${p.id==='reader'?'附件保存与恢复已经形成可试用版本。接下来继续全文检索；真机 OCR 的设备缺口已单独记录，不影响这部分推进。':p.id==='kanzei'?'当前正在验证搜索与引用链路。相关选择已留在决策复核，项目进度会同步到工作台。':'项目目标和上次的工作记录已保留，安排下一项工作后继续。'}</p></div>${(messages.get(key)||[]).map(m=>`<div class="message"><small>你 · 示例输入已记录</small><p>${escape(m)}</p></div>`).join('')}</div><form class="composer" data-chat-form="${key}"><textarea name="message" aria-label="项目对话输入" placeholder="给这个项目补充说明…" required>${escape(drafts.get(key)||'')}</textarea><div class="composer-footer"><span>${p.name} · 子代理${p.subagents?'可用':'关闭'}</span><button class="primary" type="submit">发送 ↑</button></div></form></div></div>`;}
function reviewRow(r){const p=project(r.project);return `<article class="pending-row" data-review="${r.id}"><div class="pending-origin">${p.name} / ${p.work.id} · ${r.label}</div><h3>${r.title}</h3><p>${r.body}</p><details><summary>${r.kind==='delivery'?'查看交付说明':'查看选择理由'}</summary><p class="inline-note">${r.reason}</p></details><div data-review-body="${r.id}">${r.done?`<p class="done-message">${escape(r.result)}</p>`:r.kind==='delivery'?`<div class="pending-actions"><button class="primary" data-accept="${r.id}">我已试用，通过</button><button class="quiet" data-delivery="${r.id}">查看示例成果</button></div>`:`<div class="pending-actions"><button data-accept="${r.id}">本次通过</button><button class="quiet" data-correct="${r.id}">纠正并反馈</button><a href="${pRoute(p,'conversations')}">进入原对话 ↗</a></div><div data-form-host="${r.id}"></div>`}</div></article>`;}
function inbox(filter){const items=reviews.filter(r=>!filter||r.project===filter);return `<div class="page-head"><div><div class="eyebrow">REVIEW</div><h1>待我处理</h1><p>集中试用成果，复核那些替你做出的选择。</p></div><select class="filter" id="inbox-filter" aria-label="筛选待处理项目"><option value="">全部项目</option>${projects.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><p class="muted">本次通过只认可这次决定；纠正时可以选择记忆范围。</p>${items.length?items.map(reviewRow).join(''):'<p class="empty">这个项目暂时没有待处理事项。</p>'}`;}
function preferencePage(){return `<div class="page-head"><div><div class="eyebrow">PREFERENCES</div><h1>记忆与偏好</h1><p>保留已确认的习惯，并明确它们适用于哪里。</p></div></div>${preferences.map(p=>`<div class="preference-row"><small>${escape(p.scope)}</small><p>${escape(p.text)}</p><small>${p.source}</small></div>`).join('')}<p class="inline-note">模型自己的决定不会自动成为你的全局偏好。图谱和更多管理工具在正式产品中按需进入。</p>`;}
function settings(){return `<div class="page-head"><div><div class="eyebrow">SETTINGS</div><h1>设置</h1><p>全局默认提供起点，项目可以覆盖。</p></div></div><section class="section-block"><h3>执行预算 · 设计建议</h3><div class="simple-line">同时推进的项目<span>最多 2 个</span></div><div class="simple-line">每个项目的主执行线<span>默认 1 条</span></div><div class="simple-line">新项目子代理<span>默认关闭，按需开启</span></div><div class="simple-line">普通启动页面<span>工作台</span></div><p class="inline-note">这些是本原型的建议值。正式迁移保留用户已有设置，再用阅读器实验校准预算。</p></section>`;}
function render(){const hash=location.hash||'#home';if(previousRoute)scrolls.set(previousRoute,window.scrollY);const parts=hash.slice(1).split('/');const p=project(parts[1]);let html,crumb='全局 / 工作台';if(parts[0]==='project'&&p){const tab=['overview','work','conversations'].includes(parts[2])?parts[2]:'overview';html=projectPage(p,tab,parts[3]);crumb=`<a href="#home">工作台</a> / ${p.name}`;}else if(parts[0]==='inbox'){html=inbox(p?.id);crumb='全局 / 待我处理';}else if(parts[0]==='preferences'){html=preferencePage();crumb='全局 / 记忆与偏好';}else if(parts[0]==='settings'){html=settings();crumb='全局 / 设置';}else{html=home();}$('#main').innerHTML=html;$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');$('#breadcrumb').innerHTML=crumb;document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===(parts[0]||'home');el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.querySelectorAll('[data-project-nav]').forEach(el=>{const active=parts[0]==='project'&&el.dataset.projectNav===p?.id;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});counts();previousRoute=hash;$('#main').focus({preventScroll:true});window.scrollTo(0,scrolls.get(hash)||0);}
function showDetail(p){$('#detail-content').innerHTML=`<div class="eyebrow">${p.name} / ${p.work.id}</div><h2 id="detail-title">${p.work.title}</h2>${meter(p)}<p class="muted">已完成批次，不代表用户验收。</p><ul class="info-list"><li><span>业务状态</span>${p.work.status} · ${p.work.priority}</li><li><span>当前阶段</span><span data-next="${p.id}" style="font-size:12px;color:var(--ink)">${p.next}</span></li><li><span>机器验证</span>${p.id==='reader'?'当前交付版本通过；OCR未验证':p.id==='kanzei'?'搜索链路验证中':'尚未开始'}</li><li><span>用户试用</span>${p.id==='reader'?(reviews.find(r=>r.id==='delivery-reader').done?'本次已认可':'附件保存与恢复待试用'):'暂无新交付'}</li><li><span>归属</span>${p.name} / ${p.active?'主线':'未领取'}</li></ul><h3>下一步</h3><p class="muted">${p.note}</p><div class="form-actions"><a href="${pRoute(p,'work')}" class="link-button" data-close-detail>进入项目工作 →</a></div>`;$('#detail').showModal();}
function capabilities(p){$('#detail-content').innerHTML=`<div class="eyebrow">${p.name}</div><h2 id="detail-title">项目能力</h2><p class="muted">需要时开启，状态归属于当前项目。</p><div class="simple-line">子代理<button class="toggle ${p.subagents?'on':''}" role="switch" aria-checked="${p.subagents}" aria-label="${p.name}子代理" data-toggle-agent="${p.id}">${p.subagents?'已开启':'已关闭'}</button></div><p class="inline-note">全局默认关闭；${p.subagents?'本项目已覆盖为开启':'本项目当前关闭'}。当前运行 0 个。</p><p class="muted">关闭后不再派发新的子代理；已运行的子代理继续收尾，停止在途任务使用单独动作。</p><h3>按需打开</h3><ul class="info-list"><li>文件、差异与预览</li><li>研究与远端实验</li><li>记忆图谱与运行画像</li></ul><p class="muted">这些能力收进项目工具；不在工作台持续加载。本原型仅演示子代理开关。</p>`;$('#detail').showModal();}
function correction(id){const host=$(`[data-form-host="${id}"]`);if(!host)return;const value=drafts.get(id)||'';host.innerHTML=`<form class="review-form" data-correction-form="${id}"><label>希望如何修改<textarea name="feedback" required maxlength="2000" rows="3" placeholder="写下希望的调整，以及适用条件">${escape(value)}</textarea></label><div class="form-actions"><select name="scope" aria-label="纠正适用范围"><option value="once">仅这次，不记为偏好</option><option value="project">本项目，记住偏好</option><option value="global">所有项目，记住偏好</option></select><button class="primary" type="submit">保存纠正</button></div></form>`;host.querySelector('textarea').focus();}
function finishReview(r,result){r.done=true;r.result=result;$(`[data-review-body="${r.id}"]`).innerHTML=`<p class="done-message">${escape(result)}</p>`;counts();}
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-new-goal')){const chosen=el.dataset.newGoal;$('#goal-project').innerHTML=projects.map(p=>`<option value="${p.id}" ${chosen===p.id?'selected':''}>${p.name}</option>`).join('');$('#new-goal').showModal();}if(el.dataset.detail)showDetail(project(el.dataset.detail));if(el.dataset.capabilities)capabilities(project(el.dataset.capabilities));if(el.matches('.close-dialog,[data-close-detail]'))$('#detail').close();if(el.matches('.close-goal'))$('#new-goal').close();if(el.dataset.toggleAgent){const p=project(el.dataset.toggleAgent);p.subagents=!p.subagents;el.classList.toggle('on',p.subagents);el.setAttribute('aria-checked',p.subagents);el.textContent=p.subagents?'已开启':'已关闭';el.parentElement.nextElementSibling.textContent=`全局默认关闭；本项目${p.subagents?'已覆盖为开启':'当前关闭'}。当前运行 0 个。`;document.querySelectorAll(`[data-agent-label="${p.id}"]`).forEach(node=>{node.textContent=p.subagents?'可用 · 当前 0 个':'关闭';});toast('示例项目设置已更新');}if(el.dataset.chat){const [pid,cid]=el.dataset.chat.split('/');location.hash=pRoute(project(pid),'conversations',cid);}if(el.dataset.newChat){const p=project(el.dataset.newChat);const id='new'+p.conversations.length;p.conversations.push({id,title:'新的项目对话'});location.hash=pRoute(p,'conversations',id);}if(el.dataset.correct)correction(el.dataset.correct);if(el.dataset.accept){const r=reviews.find(r=>r.id===el.dataset.accept);finishReview(r,r.kind==='delivery'?'本次试用已认可':'本次选择已认可，未新增偏好');}if(el.dataset.delivery){showDetail(project('reader'));} });
document.addEventListener('change',event=>{if(event.target.id==='project-filter'){const value=event.target.value;document.querySelectorAll('.project-row').forEach(row=>{row.hidden=value!=='all'&&row.dataset.active!==String(value==='active');});}if(event.target.id==='inbox-filter')location.hash='#inbox'+(event.target.value?'/'+event.target.value:'');});
document.addEventListener('input',event=>{if(!event.target.matches('textarea'))return;const form=event.target.closest('form');if(form?.dataset.correctionForm)drafts.set(form.dataset.correctionForm,event.target.value);if(form?.dataset.chatForm)drafts.set(form.dataset.chatForm,event.target.value);});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();if(form.id==='goal-form'){const p=project($('#goal-project').value);const value=$('#goal-text').value.trim();if(!value)return;p.goals.push(value);$('#new-goal').close();form.reset();location.hash=pRoute(p,'work');if(location.hash===previousRoute)render();toast('示例目标已保存，尚未启动执行');}if(form.dataset.correctionForm){const r=reviews.find(r=>r.id===form.dataset.correctionForm);const p=project(r.project);const feedback=form.elements.feedback.value.trim();if(!feedback)return;const scope=form.elements.scope.value;p.goals.push('决策返工：'+feedback);if(scope!=='once')preferences.push({scope:scope==='global'?'所有项目':p.name,text:feedback,source:'来自本次明确纠正 · 示例'});drafts.delete(r.id);finishReview(r,`修改已排入 ${p.name} 的原工作线${scope==='once'?'；仅本次':scope==='global'?'；已记录全局偏好':'；已记录项目偏好'}`);toast('示例纠正已保存');}if(form.dataset.chatForm){const key=form.dataset.chatForm;const value=form.elements.message.value.trim();if(!value)return;messages.set(key,[...(messages.get(key)||[]),value]);drafts.delete(key);render();toast('示例输入已保存；未调用模型');}});
$('#simulate').addEventListener('click',()=>{const p=project('reader');updateCount++;p.work.done=Math.min(4,p.work.done+1);p.next=p.work.done>=4?'准备阅读与检索的集中试用':'全文检索批次已形成版本';p.updated='刚刚有进展';document.querySelectorAll('[data-meter="reader"]').forEach(el=>{el.innerHTML=meter(p).replace(/^<span[^>]+>|<\/span>$/g,'');});document.querySelectorAll('[data-next="reader"]').forEach(el=>{el.textContent=p.next;});document.querySelectorAll('[data-updated="reader"]').forEach(el=>{el.textContent=p.updated;});$('#freshness').textContent=`已同步 · 第 ${updateCount} 次更新`;toast('仅更新阅读器进度；当前页面与输入保持');});
$('#project-nav').innerHTML=projects.map(p=>`<a href="${pRoute(p)}" data-project-nav="${p.id}" class="${p.active?'':'idle'}"><i aria-hidden="true"></i>${p.name}</a>`).join('');
window.addEventListener('hashchange',()=>{if($('#detail').open)$('#detail').close();render();});
render();
